// Generated by `hct contract generate` from the toolkit contract definitions. Do not edit.
//
// The page registry: every page a store domain serves, which part of the
// platform serves it, who may see it and how long it may be cached; the
// slots a template may fill on the platform's own pages. Also the standard
// template settings and the design token table.

/** PageId is any page in the registry. */
export type PageId = 'home' | 'domains' | 'catalog.group' | 'catalog.service' | 'not-found' | 'checkout.plan' | 'checkout.domains' | 'checkout.success' | 'checkout.cancel' | 'checkout' | 'login' | 'signup' | 'forgotpassword' | 'auth' | 'connect' | 'order' | 'dashboard' | 'admin'

/** EnginePageId is a page the rendering engine renders from a template. */
export type EnginePageId = 'home' | 'domains' | 'catalog.group' | 'catalog.service' | 'not-found' | 'checkout.plan' | 'checkout.domains' | 'checkout.success' | 'checkout.cancel'

export type Tier = 'open' | 'checkout' | 'guarded' | 'private' | 'staff'

export type Upstream = 'engine' | 'frontend'

/** CachePolicy is how long a rendered page may be served from cache, in seconds. */
export interface CachePolicy {
  /** Seconds a rendered page is fresh. */
  ttl: number
  /** Seconds a stale copy may be served while a fresh one renders. */
  swr: number
}

/** RegistryPage is one page of the registry. */
export interface RegistryPage {
  id: PageId
  /** The canonical path: the first of paths. Null for a page no path reaches. */
  path: string | null
  /** Every path the page is reached by, the canonical one first; empty for a page no path reaches. */
  paths: readonly string[]
  /** True when the page also owns every path below its own, on a "/" boundary. */
  prefix: boolean
  tier: Tier
  upstream: Upstream
  /**
   * Set for checkout pages: who serves the page when its upstream does not for a store. A
   * checkout page is rendered from the store's template when the template implements it and
   * the platform has it enabled for the store, and otherwise by the platform's front end.
   */
  fallback: Upstream | null
  /** Set for engine pages. A store's own per-page setting overrides it. */
  cache: CachePolicy | null
  /** What a store must offer for the page to exist. */
  requires: 'domains' | null
}

